  3	final class BellmanFord {
  4	    private static final int INF = 100_000_000;
  5	    private static final int FROM_INDEX = 0;
  6	    private static final int TO_INDEX = 1;
  7	    private static final int WEIGHT_INDEX = 2;
  8	    private static final int EDGE_FIELD_COUNT = 3;
