 10	    private BellmanFord() {
 11	    }
 12	
 13	    static int[] bellmanFord(int vertexCount, int[][] edgeData, int source) {
 14	        Graph graph = Graph.from(vertexCount, edgeData);
 15	        graph.validateSource(source);
 16	        return shortestPathsFrom(graph, source);
 17	    }
 18	
 19	    private static int[] shortestPathsFrom(Graph graph, int source) {
 20	        int[] dist = new int[graph.vertexCount];
 21	        Arrays.fill(dist, INF);
 22	        dist[source] = 0;
 23	
 24	        for (int i = 1; i < graph.vertexCount; i++) {
 25	            if (!relaxEdges(graph.edges, dist)) {
 26	                break;
 27	            }
 28	        }
 29	
 30	        if (hasReachableNegativeCycle(graph.edges, dist)) {
 31	            return new int[]{-1};
 32	        }
 33	
 34	        return dist;
 35	    }
 36	
 37	    private static boolean relaxEdges(Edge[] edges, int[] dist) {
 38	        boolean changed = false;
 39	
 40	        for (Edge edge : edges) {
 41	            if (canRelax(dist, edge)) {
 42	                dist[edge.to] = dist[edge.from] + edge.weight;
 43	                changed = true;
 44	            }
 45	        }
 46	
 47	        return changed;
 48	    }
 49	
 50	    private static boolean hasReachableNegativeCycle(Edge[] edges, int[] dist) {
 51	        for (Edge edge : edges) {
 52	            if (canRelax(dist, edge)) {
 53	                return true;
 54	            }
 55	        }
 56	
 57	        return false;
 58	    }
 59	
 60	    private static boolean canRelax(int[] dist, Edge edge) {
 61	        return dist[edge.from] != INF && dist[edge.from] + edge.weight < dist[edge.to];
 62	    }
 63	
 64	    private static final class Edge {
 65	        private final int from;
 66	        private final int to;
 67	        private final int weight;
 68	
 69	        private Edge(int from, int to, int weight) {
 70	            this.from = from;
 71	            this.to = to;
 72	            this.weight = weight;
 73	        }
 74	
 75	        private boolean isWithin(int vertexCount) {
 76	            return from >= 0 && from < vertexCount && to >= 0 && to < vertexCount;
 77	        }
 78	    }
 79	
 80	    private static final class Graph {
 81	        private final int vertexCount;
 82	        private final Edge[] edges;
 83	
 84	        private Graph(int vertexCount, Edge[] edges) {
 85	            this.vertexCount = vertexCount;
 86	            this.edges = edges;
 87	        }
 88	
 89	        private static Graph from(int vertexCount, int[][] edgeData) {
 90	            if (vertexCount < 0) {
 91	                throw new IllegalArgumentException("Vertex count cannot be negative");
 92	            }
 93	
 94	            if (edgeData == null) {
 95	                throw new IllegalArgumentException("Edges cannot be null");
 96	            }
 97	
 98	            Edge[] edges = new Edge[edgeData.length];
 99	            for (int i = 0; i < edgeData.length; i++) {
100	                edges[i] = parseEdge(vertexCount, edgeData[i], i);
101	            }
102	
103	            return new Graph(vertexCount, edges);
104	        }
105	
106	        private static Edge parseEdge(int vertexCount, int[] edgeData, int index) {
107	            if (edgeData == null || edgeData.length != EDGE_FIELD_COUNT) {
108	                throw new IllegalArgumentException("Edge " + index + " must contain from, to, and weight");
109	            }
110	
111	            Edge edge = new Edge(edgeData[FROM_INDEX], edgeData[TO_INDEX], edgeData[WEIGHT_INDEX]);
112	            if (!edge.isWithin(vertexCount)) {
113	                throw new IllegalArgumentException("Edge " + index + " references a vertex outside the graph");
114	            }
115	
116	            return edge;
117	        }
118	
119	        private void validateSource(int source) {
120	            if (source < 0 || source >= vertexCount) {
121	                throw new IllegalArgumentException("Source vertex is out of range");
122	            }
123	        }
124	    }
